INSERT INTO `events` (`id`, `events_headlines`, `events_details`, `events_file`, `events_status`, `events_creation_time`) VALUES
(109, 'ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়ের পুনর্মিলনী', 'লক্ষ্মীপুরের ভবনীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়ের প্রাক্তণ শিক্ষার্থীদের মিলনমেলা অনুষ্ঠিত হয়েছে। শুক্রবার বিকেলে ঢাকা বিশ্ববিদ্যালয়ের বাণিজ্য অনুষদের ড. এম হাবিবুল্লাহ মিলনায়তনে পুনর্মিলনীর  আয়োজন করা হয়। এ সময় ভবানীগঞ্জ হাই স্কুল ওল্ড স্টুডেন্টস অ্যাসোসিয়েশনের উদ্বোধন করেন মিলনমেলা আয়োজক কমিটির আহ্বায়ক হাসিনা আক্তার। তিনি সংগঠনটির উদ্যোক্তা ও প্রতিষ্ঠাতা হিসেবে ঢাবির আন্তর্জাতিক সম্পর্ক (আইআর) বিভাগের শিক্ষার্থী আরিফ চৌধুরী শুভর নাম ঘোষণা করেন।\r\n\r\nএসময় উপস্থিত ছিলেন ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়ের প্রাক্তণ শিক্ষক মো. গিয়াস উদ্দিন, মো. রফিকুল ইসলাম, প্রাক্তণ শিক্ষার্থী ও বাংলাদেশ সুপ্রিম কোর্টের আইনজীবী এম এন জামান, পরিকল্পনা মন্ত্রণালয়ের সিনিয়র সহকারী সচিব সালাহ উদ্দিন আতিক, ঢাকা বিশ্ববিদ্যালয়ের অ্যাকাউন্টিং বিভাগের সহকারী অধ্যাপক সাইফুল আলম ফুয়াদ, নৌ-বাহিনীর ক্যাপ্টেন ইকবাল চৌধুরী, ক্যাটস আই’র পরিচালক আশরাফ উদ্দিন শিপলু, উইনক্লো লিমিটেডের ব্যবস্থাপনা পরিচালক আতাউর রাব্বি, ফার সিরামিকসের ডেপুটি জেনারেল ম্যানেজার (মার্কেটিং) মাহবুবুর রহমান, চৈতি গ্রুপের এইচ আর হেড মিজানুর রহমান, ব্যাংকার সৈয়দ পারভেজ, নজরুল ইসলাম, মোস্তাফিজুর রহমান, মারজাহান আক্তার ও জাকির হোসেন, সানা উল্যাহ প্রমুখ।\r\n\r\n\r\nভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয় ১৯৪৭ সালে প্রতিষ্ঠিত হওয়ার পর থেকেই গ্রামীণ ছেলেমেয়েদের মাঝে শিক্ষার আলো ছড়াচ্ছে।', '1690484990.jpg', '1', '2023-02-03 06:15:56.883913'),
(110, 'বিদ্যালয়ের ম্যানেজিং কমিটির সভাপতি নির্বাচিত হয়েছেন জনাব নাসির উদ্দিন রাজু', 'নতুন সভাপতি হিসেবে রাজুর নাম প্রকাশ হওয়ার পর স্থানীয় সর্বস্তরের মানুষের মাঝে সন্তোষ বিরাজ করে। ইতিমধ্যে শুভাকাংখী শিক্ষানুরাগীরা সামাজিক যোগাযোগ মাধ্যম ফেসবুক সহ বিভিন্ন মাধ্যমে তাঁকে অভিনন্দন জানিয়েছেন। এর মধ্য দিয়ে বিদ্যালয়ের দীর্ঘদিনের ঝিমিয়ে পড়া শিক্ষা ব্যাবস্থার মানোন্নয়ন হবে বলে ধারনা করছেন স্থানীয়রা। জানা যায়,ভবানীগঞ্জ এলাকার খেলাধূলা,শিক্ষা-সংস্কৃতি সহ বিভিন্ন উন্নয়নে নাসির উদ্দিন রাজু দীর্ঘদিন থেকে একাধিক সংগঠনের সাথে দায়িত্ব নিয়ে সম্পৃক্ত রয়েছেন। ব্যাক্তিগত জীবনে তিনি শিক্ষিত সৎজন বলে পরিচিতি রয়েছে। এছাড়া তিনি একজন শিল্পোদ্যেক্তা। তিনি ভবানীগঞ্জ সরকারী প্রাথমিক বিদ্যালয়ের সভাপতি,ভবানীগঞ্জ ক্রীড়া সংস্থার প্রতিষ্ঠাতা ও সামাজিক সংগঠন চলন্তিকা ক্লাব এর উপদেষ্টা। এছাড়া একাধিক মসজিদ,মাদ্রাসা,সামাজিক ও স্বেচ্ছাসেবী সংগঠনের সাথেও তিনি জড়িত রয়েছেন। স্থানীয় নেতৃত্বে রাজু একজন সম্ভাবনাময়ী বলেও জানায় এলাকাবাসী জানায়। জানতে চাইলে নব নির্বাচিত সভাপতি নাসির উদ্দিন রাজু বলেন,”ভবানীগঞ্জ উচ্চ বিদ্যালয়ের ফিকে হয়ে যাওয়া ঐতিহ্য ফিরিয়ে আনতে সর্বাত্মক প্রচেষ্টা করা হবে। বিদ্যালয়ের লেখাপড়া,খেলাধূলার মানোন্নয়ন সহ আনুষঙ্গিক সকল বিষয়ে বিদ্যালয়ের স্বার্থকে প্রাধান্য দিয়ে উদ্যেগ করা হবে।” এ লক্ষ্যে তিনি সকলের আন্তরিক সহযোগীতা কামনা করেছেন।', '1690484929.jpg', '1', '2023-02-03 06:17:57.355235'),
(113, 'প্রধান শিক্ষক ও কম্পিউটার ল্যাব অপারেটর নিয়োগ বিজ্ঞপ্তি', 'জনবল কাঠামো এবং এমপিও বিধিমালা-২০২১ অনুযায়ী ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়ে সরকারি বিধিমোতাবেক ১ জন প্রধান শিক্ষক ও ১ জন কম্পিউটার ল্যাব অপারেটর নিয়োগ করা হবে। বিজ্ঞপ্তি প্রকাশের ২১ দিনের মধ্যে আগ্রহী প্রার্থীদেরকে https://forms.gle/eVKvJQX3prZy5Tjk6 এই লিঙ্কে গিয়ে আবেদন ফরম পূরণ করে সভাপতি, বিদ্যালয় পরিচালনা পর্ষদ, ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়ের অনুকূলে প্রধান শিক্ষক পদের জন্যে ১,০০০ টাকার এবং কম্পিউটার ল্যাব অপারেটর পদের জন্যে ৭০০ টাকার (অফেরতযোগ্য) পে-অর্ডারসহ আবেদন করতে হবে। পূরণকৃত আবেদন ফরমের প্রিন্টেড কপি, শিক্ষাগত যোগ্যতা এবং অভিজ্ঞতার সনদসহ যাবতীয় কাগজপত্র সভাপতি, বিদ্যালয় পরিচালনা পর্ষদ, ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়, ভবানীগঞ্জ, লক্ষ্মীপুর বরাবর প্রেরণ করতে হবে। যোগাযোগ:- সভাপতি, ভবানীগঞ্জ বহুমুখী উচ্চ বিদ্যালয়,ডাকঘর: ভবানীগঞ্জ, উপজেলা: সদর, জেলা: লক্ষ্মীপুর। মোবাইল:-01716677599', '1690484809.jpg', '1', '2023-07-27 19:06:49.697065');
